    "kcs-article": { s1: ["sup: Capture in the user's words while solving."], s2: ["i18n: Language and locale noted for each article."], s3: ["priv: No personal data or credentials."], d1: ["sup: Would another agent solve it from this alone?"], s4: ["a11y: Article readable with a screen reader.", "cust: Findable with the words users search."] },
    "forecast-demand": { s1: ["biz: Sales plan and new customers included.", "dom: Rollout dates by site."], s2: ["infra: Peak hour, not just peak day.", "perf: Arrival pattern — 08:00 batches."], s3: ["fin: Back-test error reported."], d1: ["biz: Business owner agrees the scenarios."], s4: ["infra: Forecast shared with platform and vendors."] },
