    "cost-to-serve": { s1: ["fin: Every invoice and usage line collected."], s2: ["infra: Tags cover at least 95% of spend.", "vendor: Vendor charges split by service."], s3: ["fin: Unit cost and value per order."], d1: ["fin: Reconciled to invoices."], s4: ["biz: Is the service paying its way?"] },
    "right-size": { s1: ["fin: Idle, oversized or duplicated spend.", "vendor: Unused licences and tiers."], s2: ["rel: SLO risk of each saving.", "perf: Latency impact assessed."], d1: ["fin: Is the saving worth the risk?"], s3: ["eng: Change reviewed like code."], s4: ["rel: SLOs unchanged after the change."] },
    "triage-vuln": { s1: ["sec: Findings matched to what actually runs (SBOM)."], s2: ["sec: Exploitability and exposure, not CVSS alone.", "vendor: Vendor-hosted components included."], d1: ["sec: Above threshold → SLA by risk."], s3: ["devops: Hotfix through the pipeline.", "ops: Redeploy within the error budget where possible."], s4: ["comp: Evidence kept for audit."] },
    "tune-detections": { s1: ["sec: Each high threat from the threat model covered."], s2: ["priv: No personal data in security logs beyond need.", "infra: Log sources reliable and complete."], s3: ["data: Rules use well-defined fields."], d1: ["sec: Fires on simulation, quiet otherwise."], s4: ["ops: Routed to someone who will act."] },
    "contain-threat": { s1: ["sec: Real attack or false positive?"], d1: ["sec: Confirm before disruptive action, unless harm is ongoing."], s2: ["sec: Revoke, isolate, block — preserve evidence first.", "data: Which data was reachable?"], s3: ["ops: Recovery verified on the SLIs."], s4: ["priv: Personal-data breach assessed within 72 h.", "legal: Contractual notification duties to customers.", "comp: Regulator notified when required.", "cust: Affected customers told plainly."] },
    "access-review": { s1: ["sec: Every account and token with order or ERP scope."], s2: ["gov: Owners recertify, not the security team.", "vendor: Vendor support accounts included."], d1: ["sec: Least privilege — every access justified."], s3: ["priv: Leavers removed the day they leave."], s4: ["comp: Evidence kept for audit."] },
